// (src/lib/shard.ts) — подгружается, когда раскрывают «Сюжет» (src/api, getPlot). Не править руками.
export const blurbs: Record<string, string> = {
 "f-wd319163": "Злая мачеха заставляла её работать, не давая продыху. Однажды она решила избавиться от падчерицы и отправила ту замерзать в зимний лес. В этих же краях жил паренёк Иван. Он полюбил Настеньку, да вот только был он большим хвастуном, потому лесной колдун и превратил его в медведя. И Настеньке, и Ивану пришлось пройти через много испытаний, прежде чем соединить свои судьбы.",
 "f-wd23562553": "Физик-ядерщик Барри Аллен в ходе неудачного научного эксперимента подвергается серьёзному облучению ядохимикатами. Но, к собственному удивлению, не погибает, а приобретает новые поразительные способности. Благодаря метаморфозам, произошедшим из-за облучения в его ДНК, герой теперь способен развивать невообразимую скорость.",
 "f-wd29466808": "Доминик Торетто ведет спокойную жизнь вместе с Летти и сыном Брайаном, но новая опасность всегда где-то рядом. В этот раз Доминику придется встретиться с призраками прошлого, если он хочет спасти самых близких. Команда снова собирается вместе, чтобы предотвратить дерзкий план по захвату мира, который придумал самый опасный преступник и безбашенный водитель из всех, с кем они сталкивались ранее. Ситуация усложняется тем, что этот человек — брат Доминика Джейкоб, которого много лет назад изгнали из семьи.",
 "f-wd20430699": "Во время обследования удаленной планеты, расположенной на другой стороне галактики, экипаж колониального корабля «Завет» обнаруживает, что то, что они изначально приняли за неизведанный рай, на самом деле - тёмный и опасный мир. Его единственный житель - синтетический андроид Дэвид, оставшийся в живых после обреченной экспедиционной миссии «Прометей».",
 "f-wd20968495": "Раннее Средневековье. Время тяжелых мечей и темных законов крови. Правящий род в раздоре. Вина за случайную смерть брата легла на Великого Князя. По закону мстить ему должен младший брат - бастард. За отказ убивать он заплатит всем, что у него было, потому что «для мира нужно больше мечей, чем для войны»...",
 "f-wd14650496": "Они покорили Токио и Рио, Лос-Анджелес и Лондон. Но мир больше не играет по их правилам. Зной арабских пустынь, неприлично высокие небоскребы, миллионы долларов на колесах и очень, очень знаменитый злодей. Скорость не знает границ.",
 "f-wd2306068": "Восточный берег Каспия. Гражданская война. Отряд красного командира Рахимова гоняется по пескам за бандитом Абдуллой и его головорезами. Погоня осложняется тем, что приходится возить с собой жён жестокого басмача, спасая их от верной гибели. Возиться с пугливыми восточными красавицами, укутанными в паранджу, нет уже никаких сил. Рахимов перепоручает заботу о женском коллективе случайно встреченному посреди унылых пейзажей товарищу Сухову, определив ему в помощь молодого бойца Петруху.",
 "f-wd213326": "История семьи супергероев, члены которой уже отошли от больших дел и предпочитают жить непримечательной жизнью обычных землян. В прошлом все они обладали сверхъестественными способностями и относительно легко справлялись с мировым злом. Но в один прекрасный день папаше и его домочадцам приходится вновь облачиться в прорезиненные костюмы супергероев (а для этого нужно срочно сбросить лишние килограммы!) и в очередной раз спасти человечество от таинственного злодея…",
 "f-wd1528731": "Участвуя в программе на телевидении, Данила Багров встречает своих друзей по Чечне. Одного из них внезапно убивают. Данила знает, что у убитого были неприятности из-за брата — хоккеиста, играющего за американский клуб. Данила должен разобраться. Он вылетает в Америку и для компании берёт с собой брата. Теперь его фотография ходит по рукам русской и американской мафии. Новоявленные «Аль Капоне» понимают, что нарвались на профессионала…",
 "f-wd129193": "Спасение Долины Мира и всех ее обитателей от непобедимого и безжалостного мастера Тай Лунга должно лечь на плечи Воина Дракона, Избранного среди лучших из лучших, коим становится… неуклюжий, ленивый и вечно голодный панда По.\r Ему предстоит долгий и трудный путь к вершинам мастерства кунг-фу бок о бок с легендарными воинами: Тигрой, Обезьяной, Богомолом, Гадюкой и Журавлем. По постигнет тайну древнего Свитка и станет Воином Дракона только в том случае, если сможет поверить в себя…",
 "f-wd126396314": "Изгнанный из клана хищник Дек отправляется на опасную планету Генна. Он стремится доказать своему отцу и всему племени, что достоин быть частью клана. Дек встречает загадочную девушку-андроида Тию и объединяется с ней, чтобы отправиться на поиски сверххищника Калиска, наиболее грозного противника на планете.",
 "f-wd110617876": "События разворачиваются в будущем, во время войны между людьми и искусственным интеллектом. Бывший спецназовец Джошуа вместе с отрядом оперативников получает задание найти и убить архитектора продвинутого искусственного интеллекта — Создателя, который разработал оружие, способное положить конец не только войне, но и всему человечеству.",
 "f-wd111538862": "Недалёкое будущее, в США бушует гражданская война. Объединённые силы Запада — Калифорнии и Техаса — уже близки к взятию Вашингтона. Двое опытных военных корреспондентов и присоединившиеся к ним ветеран журналистики и начинающая девушка-фотограф отправляются из Нью-Йорка в столицу, чтобы успеть взять интервью у забаррикадировавшегося в Белом доме президента, прежде чем до него доберётся противник.",
 "f-wd104830968": "3-ое друзей - врач, медсестра и адвокат, спустя годы вновь встречаются и неожиданно оказываются главными подозреваемыми в громком убийстве. Пытаясь доказать свою невиновность, они начинают собственное расследование, которое приводит их к масштабному заговору, связанному с влиятельными людьми и событиями, способными изменить судьбу целой страны.",
 "f-wd110237375": "От любящей родни не уйдешь. Суровая Вера Павловна отправляется в лихую погоню за своей внучкой Машей и непутёвой дочерью Олей. Помогает ей в этом Олег — все еще влюбленный в Олю «бывший», даже после того, как посадил за решетку. Кажется, во всей этой уморительной суматохе только маленькая Маша знает, как взрослым не слететь с катушек.",
 "f-wd289204": "Саксофониста Фреда Мэдисона обвиняют в жестоком убийстве своей жены Рене и приговаривают к смертной казни. Незадолго до исполнения приговора он таинственным образом исчезает из камеры смертников, а на его месте находят растерянного и ничего не понимающего автомеханика Пита Дейтона. Выпущенный на свободу, Пит пытается вернуться к повседневной жизни, но постепенно погружается в необъяснимый кошмар.",
 "f-wd105095144": "Ветеран Уилл Шарп отчаянно нуждается в деньгах, чтобы спасти смертельно больную жену. Он обращается за помощью к брату-преступнику Дэнни, и тот уговаривает его ограбить банк. Однако всё идет не по плану, и братьям приходится угнать машину скорой помощи вместе с двумя заложниками — врачом и раненым полицейским.",
 "f-wd23796644": "Он — телохранитель мирового уровня. Его новая работа — охранять киллера, которого все мечтают убить. Он и сам с удовольствием прикончил бы этого гада. Но работа — есть работа: смертельные враги в прошлом, они вынуждены объединиться в настоящем, чтобы выжить. Однако их методы настолько различны, а принципы противоположны, что вопрос выживания — под большим вопросом.",
 "f-wd23013169": "Готэму вновь грозит опасность. И на его стражу становится единственный герой, которого заслуживает этот город — Бэтмен, альтер-эго миллиардера Брюса Уэйна, живущего в своём огромном родовом поместье вместе с дворецким Альфредом. Но в этот раз супергерой вынужден взять в напарники парня по имени Дик Грейсон, которого он, сам того не помня, усыновил на одном из светских приемов. Новоиспеченный Робин составит Бэтмену компанию в борьбе с его заклятым врагом Джокером, сбежавшим из психиатрической больницы «Аркхем».",
 "f-wd15055043": "Воссоединившись со своим давно потерянным отцом, По отправляется в тайный рай для панд, где его ожидает встреча с множеством веселых сородичей. Однако вскоре злодей Кай начинает зачистку - он уничтожает кунг-фу мастеров по всему Китаю.\r По предстоит сделать невозможное - обучить боевому искусству деревню, полную его веселых, неуклюжих собратьев, и тем самым превратить их в отряд кунг-фу панд.",
 "f-wd643811": "Драма, номинированная на Оскар в 1957 году, рассказывает о международном конфликте, опасных приключениях, захватывающей интриге и трагической любви на фоне широкомасштабного вторжения Наполеона в Россию.",
 "f-wd18816889": "Благодаря революционной технологии, которая высвобождает генетическую память, Каллум Линч переживает приключения своего предка Агилара в Испании XV столетия. Заполучив невероятные знания и способности, Каллум сразится с рыцарями ордена тамплиеров в наше время.",
 "f-wd124435493": "Спустя 4 года после своего спасения из плена жестокого маньяка 17-летний Финн до сих пор пытается вернуться к нормальной жизни. Однако теперь его сестру, 15-летнюю Гвен, мучают загадочные сны о вновь зазвонившем чёрном телефоне. Кроме того, девушку посещают тревожные видения о трёх мальчиках в зимнем лагере. Решив разгадать загадку и положить конец их общим страданиям, Гвен уговаривает брата отправиться в лагерь из её снов.",
 "f-wd4195664": "Увлекательная история от создателей богатырской трилогии, в которой героев русских народных сказок ждут новые приключения, опасности и забавные ситуации.",
 "f-wd115931717": "Детектив Бенуа Бланк объединяет силы с молодым священником, чтобы раскрыть идеальное до невозможности преступление, совершённое в церкви небольшого городка с тёмной историей.",
 "f-wd65146722": "«4 всадника» возвращаются вместе с молодым поколением иллюзионистов, демонстрируя головокружительные трюки, магию и превращения, каких ещё не видел мир.",
 "f-wd114242678": "Осиротевший Муфаса знакомится с наследником королевских кровей по имени Така. Вместе они отправляются в судьбоносное опасное путешествие, которое проверит их дружбу на прочность.",
 "f-wd117255424": "1985 год. Торговец углем и семьянин Билл Ферлонг готовится к самому напряженному сезону в своей работе. За несколько недель до Рождества он доставляет заказ в местный монастырь и невольно становится свидетелем шокирующей истории, которая происходит за его стенами. Билл узнает, что на самом деле скрывается за «прачечными Магдалины» — специальными учреждениями при монастырях, в которые определяют женщин со сложной судьбой.",
 "f-wd124393313": "История о психологическом противостоянии талантливого психиатра Дугласа Келли и рейхсмаршала нацистской Германии Германа Геринга, от результатов которого зависит исход Нюрнбергского процесса.",
 "f-wd125933907": "Джош приобретает себе секс-андроида Айрис. Она должна во всём слушаться своего хозяина и выполнять любые его прихоти, однако со временем начинает замечать странности в окружении и своём поведении. Вскоре Айрис узнаёт, что Джош взломал её и изменил программу, чтобы создать идеальную женщину.",
 "f-wd243983": "Действие фильма происходит в современном Сан-Франциско и строится вокруг ученого, генетические эксперименты которого привели к возникновению высокоразвитого интеллекта у обезьян. Приматы, осознав свое подчиненное положение, поднимают восстание и лишают человека звания царя природы.",
 "f-wd277038": "Лента о событиях, разворачивающихся на фоне цунами 2004 года.",
 "f-wd11252497": "Главный герой, кот Шерафеттин — смелый и ироничный, веселый и нелепый. А ещё очень независимый кот, который старается решать все свои проблемы самостоятельно. Часто из этого вырастает еще больше неприятностей.",
 "f-wd187278": "Энди почти 18 лет, ему остаётся 3 дня до отправки в колледж, в то время как его игрушки, в том числе Вуди и Базз Лайтер, гадают о своём будущем. Куда забросит их судьба? На чердак, на свалку или, может быть, в детский сад «Солнышко»?",
 "f-wd20751338": "Встречайте, новый герой отправляется покорять город зверей! Он — пёс Боуди, и он не унывает, несмотря ни на что. Ему на роду написано сторожить родную деревню от волков, а он мечтает стать учеником живой рок-легенды, кота по имени Энгус. Однако у Энгуса совсем другие планы, да и волки подстерегают за каждым углом. Но если не вешать хвост, то всё в твоих лапах!",
 "f-wd202326": "Заключительная часть знаменитой гангстерской эпопеи, в которой продолжается рассказ о делах «семьи» дона Корлеоне. Через двадцать лет после событий, описанных в предыдущей картине, Майкл Корлеоне решает заняться легальным бизнесом. Однако противодействие внутри клана заставляет его вспомнить об испытанных кровавых методах общения с противником, что приводит к трагическому итогу.",
 "f-wd102754": "Бонду дано задание выяснить что является источником электронных помех в компьютерах американских пусковых шахт на мысе Канаверал. По агентурным данным мозговой центр вражеских сил находится на Ямайке. Бонд незамедлительно выдвигается туда.\r В процессе расследования ему придется столкнуться с могущественной структурой СПЕКТР и ее представителем Доктором Ноу, готовым пойти на все, лишь бы держать весь мир в своих металлических руках. И только Бонд и его верный Вальтер ППК могут остановить злые силы на знойном океанском побережье.",
 "f-wd842306": "Дональд Дак, Гуфи и попугай Жозе Кариока приглашают вас в Латинскую Америку!  Музыка, танцы, песни удачно переплетаются с чудесными видами озера Титикака, Бразилии, Уругвая и других латиноамериканских стран.",
 "f-wd47075": "Получив грин-карту в обмен на убийство кубинского правительственного чиновника, Тони Монтана заявляет о своих правах на наркобизнес в Майами. Жестоко убивая всех, кто стоит на его пути, Тони в конечном итоге становится крупнейшим наркобароном в штате, контролируя почти все поставки кокаина, проходящие через Майами. Но усиливающееся давление со стороны полиции, войны с колумбийскими наркокартелями и его собственная паранойя, вызванная наркотиками, приводят к его окончательному падению.",
 "f-wd156401": "Курочкам на ферме миссис Туиди приходится нелегко. Для каждой из этих несчастных птиц любое, даже самое погожее утро, может стать последним: в мгновение ока они могут угодить в суп или стать начинкой для пирожка.\r Безропотные домашние птички живут в постоянном страхе в ужасных курятниках, напоминающих бараки концлагеря. Все попытки вырваться из страшной фермы на волю оканчиваются провалом. Но однажды на ферме объявился весёлый американский петух Рокки...",
 "f-wd495850": "Землетрясение уничтожило дом доисторической семьи, и теперь Крудсам придётся искать другое пристанище. А вокруг новый и опасный мир! Им на помощь приходит молодой кочевник Малой, передовые взгляды которого наталкиваются на консервативность главы семьи Груга. Но только вместе они смогут выжить и достичь своей цели...",
 "f-wd230552": "Из газет 1955 года Марти узнает, что доктор Браун погиб еще сто лет назад. Несмотря на просьбы Дока не навещать его в XIX веке, Марти вновь хочет вмешаться в ход событий и на машине времени уносится в 1885 год, навстречу Дикому Западу. Это путешествие, как и все прежние, не обходится без опасных приключений, но смелый Марти, рискуя жизнью, предотвращает трагедию в жизни Эммета Брауна. Тот, в свою очередь, без памяти влюбляется в очаровательную незнакомку, которую спасает от гибели, и поездка домой - в будущее - теряет для него всякий смысл...",
 "f-wd19069": "В маленькой деревушке крестьяне годами страдают от бесчинств местных бандитов. Их главарь Калвера держит в страхе всю округу, мучая её жителей постоянными поборами и наказаниями. И однажды крестьяне решают нанять себе защитников - семерых вооруженных всадников во главе с бритоголовым Крисом. Великолепная семёрка быстро наводит порядок, но Калвейре все же удается бежать. И тогда поимка злодея и его соратников становится делом чести великолепной семёрки.",
 "f-wd232774": "Для наших героев наступили печальные будни: Сэм потерял Микаэлу, правительство выпускает законодательный акт о выселении Автоботов с Земли, а пока Мегатрон скрывается после позорного поражения Фоллена, десептикон Шокуэйв, правитель Кибертрона, готовится нанести визит нашей планете с совсем недобрыми намерениями.",
 "f-wd201215": "Знаменитый профессор Генри Хиггинс заключает пари со своим другом, что сможет обучить безграмотную замарашку, уличную цветочницу Элизу, правильной речи и высокосветским манерам и выдать ее за настоящую леди.",
 "f-wd401976": "Бывший полицейский Брайан О`Коннер вместе с бывалым лихачом Домиником Торетто совсем немного увлеклись жизнью вне закона. После того, как Брайан и Миа Торетто освободили Доминика, они не рискуют долго задерживаться на одном месте, так как являются желанной целью порядком недовольных копов.",
 "f-wd486588": "После того как король превратился в жабу, бразды правления королевством перешли Шрэку и его жене Фионе. Герои оказались не в восторге от такой перспективы, заявив что хотят спокойно жить на своём болоте. Тогда им предложили найти наследника престола – мальчугана Арти, племянника королевы Лилиан, а потом спокойно отправляться к себе домой на болото. Шрэк, Осёл и Кот отправляются в далёкое путешествие, чтобы уговорить мальчика стать королем Артуром, а Фионе в это время приходится удерживать трон, от посягательств на него принца Чарминга...",
 "f-wd244247": "Лев Алекс, зебра Марти, бегемотиха Глория и жираф Мелман, а также король Джулиан, Морис, Морт и Пингвины всё ещё пытаются вернуться в Нью-Йорк. На этот раз их путь пройдёт через Европу, где они откроют свой цирк.",
 "f-wd249967": "Граф Дракула управляет роскошным отелем, скрытым от людей, где монстры со всего мира могут спокойно отдыхать вместе со своими семьями. В честь 118-летия своей дочери Мэйвис он устраивает большой праздник, но всё меняется, когда в отель случайно попадает обычный парень по имени Джонни. Чтобы сохранить тайну и не допустить паники среди гостей, Дракула пытается скрыть присутствие человека.",
 "f-wd329805": "На мать-одиночку Мануэлу обрушивается самое ужасное из земных несчастий — в автокатастрофе погибает её единственный сын Эстебан. Подвергнувшись спонтанному порыву, убитая горем женщина возвращается в город своей бурной юности — Барселону. Там она встречается с призраком Прошлого, чьи уродливые когти безжалостно царапают судьбы людей в Настоящем. Мануэле предстоит встреча с отцом Эстебана и его окружением, от которых она сбежала шестнадцать лет назад.",
 "f-wd632668": "Коралина переезжает с родителями в старый загородный дом и вскоре обнаруживает тайную дверь, ведущую в загадочный параллельный мир. Там всё кажется лучше настоящей жизни: другие родители уделяют ей больше внимания, вокруг царят веселье и чудеса, а вместо обычных глаз у всех жителей пуговицы. Однако за этой идеальной картиной скрывается страшная тайна.",
 "f-wd221345": "Бэтмен продолжает войну со злом. На этот раз ему предстоит биться с двумя объединёнными злодеями: бывшим окружным прокурором пострадавшим от кислоты Двуликим и сумасшедшим гением Загадочником. А помогать ему станет юный акробат по имени Робин.",
 "f-wd110278": "У Дэвида было всё: деньги, свой собственный издательский дом, дорогая машина и квартира в респектабельном районе Нью-Йорка, друг-писатель и подружка Джулианна, и даже враги в лице семи управляющих его компанией. Так он и жил без оглядки, пока в один прекрасный момент не попал в автокатастрофу и очнулся после комы инвалидом с изуродованным лицом, которое теперь приходится скрывать. Его новая жизнь обернулась кошмарным сном, от которого нельзя проснуться.",
 "f-wd126800": "В музыкальном мире императорских пингвинов, которые находят себе пару благодаря пению, рождается пингвиненок по имени Мамбл, который не может издать ни одной ноты… зато может отплясывать ту еще чечетку. Его родители, Норма Джин и Мемфис в отчаянии, но надеются, что их лишенный музыкального слуха малыш перерастет свое нелепое танцевальное увлечение. Однако пытаясь пропеть хоть какую-то мелодию, он не может перестать отбивать чечетку даже ради того, чтобы завоевать любовь своей возлюбленной Глории…",
 "f-wd332368": "На этот раз агент 007 (Роджер Мур) сражается сразу с двумя преступниками. Одного из них зовут Макс Зорин (Кристофер Уокен - «Сонная лощина»), он продукт генетических исследований нацистов. Его помощница по имени Мэй-Дэй - настоящая экстремалка с безудержной тягой к преступлениям. Макс задумал уничтожить «Силиконовую долину» - центр научно-технических исследований США.",
 "f-wd57317060": "Отобрав наиболее перспективных заключенных из тюрьмы, в которой содержатся не только самые опасные преступники, но и люди со свехрспособностями, и даже не люди, правительственный агент отправляет их на самоубийственное задание в одну латиноамериканскую страну, где недавно произошел военный переворот. А чтобы те наверняка не сбежали, каждому в голову вживляется взрывное устройство.",
 "f-wd275553": "Действие картины развивается в Лос-Анджелесе 20-х годов прошлого столетия. Обратившись в полицию с заявлением об исчезновении ребенка, главная героиня вскоре получает своего сына, но сообщает полицейским, что, несмотря на внешнее сходство, это не ее сын. Вместо помощи несчастная мать получает прописку в палате клиники для сумасшедших…",
 "f-wd463620": "Танцующие певицы сестры Махони приезжают на Бродвей, где их друг Эдди Керне хочет задействовать их в одном из новых шоу Фрэнсиса Занфилда. Эдди и одна из сестер даже состоят в отношениях и намереваются обвенчаться, однако Эдди влюбляется во вторую сестру, на которую положил глаз член высшего общества Нью-Йорка Джок Уорринер…",
 "f-wd1043614": "Маленький мальчик 8 лет Ишан Авасти с рождения немного отличается от других детей. Ему дается с трудом то, что у других получается очень легко. Мир не понимает этого ребенка, как и его собственные родители. Когда Ишан в третий раз проваливает экзамены в школе, его отец в наказание отправляет мальчика в школу-интернат. Одиночество губит ребенка, он осуждает себя за расставание с родителями, но и их не может простить. Однажды в жизни Ишана появляется временный учитель рисования Рам Никум — единственный, кто понимает этого ребенка. Рам ставит перед собой цель изменить жизнь мальчика и отношение к нему.",
 "f-wd244434": "Продолжение классического диснеевского мультфильма о трогательных отношениях породистой Лесси и бездомного пса. Они уже родители целой своры щенков — трёх работящих девочек и одного буйного щенка-мальчика по прозвищу Бездельник.  В поисках риска и «реальной» собачьей жизни Бездельник уходит из дома и встречает Ангела, Бастера и его шайку. Вместе с верными друзьями он переживёт множество комичных ситуаций а также столкнётся с опасностями, которые вполне могут ожидать маленького щенка на улицах большого города. Хотя Бездельник и нашёл риск, но мысли его возвращаются к дому и родным…",
 "f-wd729991": "Молодой человек, студент престижного колледжа из очень богатой семьи, полюбил студентку из семьи очень скромного достатка, они поженились, пережили и неприятные моменты и счастливые, но вдруг ни с того ни с сего молодая жена внезапно и смертельно заболевает.",
 "f-wd660894": "Гилберт Грейп живет в штате Айова, в крошечном городке с населением в тысячу жителей. У него две сестры, слабоумный брат и толстуха-мать. Гилберт тянет лямку в магазине и крутит роман с замужней дамой. Но все меняется, когда в городок приезжает красивая молодая женщина по имени Беки.",
 "f-wd644933": "События фильма разворачиваются в ту чудесную эпоху, покрытую туманом прошлого, богатую на героев и монстров, приключения и отвагу, богатство и славу, когда одному исключительному человеку по имени Беовульф удается спасти древнее датское королевство от жуткого чудовища, истребляющего его жителей. После этого сей легендарный викинг ростом почти в два метра, полный дерзости, уверенности и удивительной амбициозности, восходит на трон. Всё чаще в королевстве звучит имя Беовульфа, о нем слагаются песни, восхваляющие его небывалую доблесть и решительность после того, как он приходит на помощь королю Хродгару, чье королевство подвергается вероломным нападкам Гренделя, беспощадного монстра, который мучает и пожирает жителей королевства, заставляя их жить в вечном ожидании страха и опасности.",
 "f-wd642546": "1953 год. В Америке идет борьба женщин за свои права, и в это время Кэтрин Энн Уотсон, выпускница Беркли, получает место преподавателя истории искусств в женском колледже Уэллесли. Однако среди руководства и преподавательского состава колледжа преобладают патриархальные взгляды на роль женщины в этом мире.  Кэтрин со страстным энтузиазмом бросается в борьбу за равноправие полов, и оказывает огромное влияние на студенток, в том числе на Бетти и Джоан. Общение с ними меняет не только их, но и заставляет ее по-новому взглянуть на собственную жизнь…",
 "f-wd236217": "Жизнь Эдит Пиаф была похожа на сражение, каждый день ей приходилось бороться за право, жить, петь и любить! Из трущоб Парижа она поднялась на подмостки Нью-Йоркских концертных залов и завладела сердцами всего мира. Ее друзьями были известнейшие люди того времени — Жан Кокто, Марлен Дитрих, Марсель Сердан. Выросшая в жуткой нищете, Пиаф достигла колоссального успеха. Но, взлетев на необозримую высоту, она не смогла не обломать крылья…",
 "f-wd390063": "Фантастическая четвёрка узнаёт, что есть во вселенной и другие существа, наделенные сверхъестественными способностями. Теперь супергероям предстоит схватка с могущественным Серебряным Серфером и поедающим планеты Галактусом.",
 "f-wd113883193": "Существует место, где можно исполнить все свои заветные желания. Однако, чтобы туда попасть, необходимо отдать своё желание таинственному королю. Принцесса Аша вместе с козлом Валентино отправляются в эпическое приключение, чтобы спасти свой народ и достичь своей заветной мечты...",
 "f-wd157556": "История, происходящая во время Второй мировой войны и показанная сквозь глаза невинного и ничего не подозревающего о происходящих событиях Бруно, восьмилетнего сына коменданта концентрационного лагеря. Его случайное знакомство и дружба с еврейским мальчиком по другую сторону ограды лагеря, в конечном счёте, приводит к самым непредсказуемым и ошеломительным последствиям.",
 "f-wd1635046": "Трогательная лирическая киноповесть о судьбе собаки, теряющей любимого хозяина, об отношении людей к «братьям меньшим», которое как рентгеном просвечивает души, выявляя в одних низость и мелочную подлость, а в других - благородство, способность сострадать и любить…",
 "f-wd2018550": "Романтическая драма по мотивам одноименной поэмы великого русского поэта Михаила Лермонтова. Ашик-Кериб был беден, но у него было доброе сердце и прекрасный голос. Он играл на саазе - турецкой балалайке, прославляя древних витязей Туркестана, выступал на празднествах и свадьбах. Однажды увидел он красавицу Магуль-Мегери, дочь турецкого богача, и полюбил ее. Но разве выдаст богач свою дочь за бедняка? Ашик-Кериб поклялся семь лет странствовать, чтобы нажить богатство или умереть. Если к назначенному сроку он не вернется, Магуль-Мегери выйдет замуж за другого...",
 "f-wd764734": "На Кавказе — война. Двух раненых русских солдат забирает житель отдаленного горного аула Абдул-Марат. Сын Абдул-Марата находится в плену у русских, и старик хочет договориться с комендантом лагеря об обмене пленными.",
 "f-wd2996571": "Фильм посвящается грузинским воинам всех времен, отдавшим жизнь за Отечество. В основе его лежит древняя грузинская легенда: готовясь к защите своей страны от нападения иноземных поработителей, народ возводил крепость, но каждый раз, когда стена достигала уровня крыши, она обрушивалась. «Стена выстоит, если в нее будет замурован самый прекрасный юноша», - сказала гадалка. И нашелся юноша, который совершил самопожертвование ради спасения Отечества. Благодаря этой жертве крепость была воздвигнута, и никто и ничто уже больше не могло ее разрушить.",
 "f-wd2376391": "В один из морозных зимних вечеров, когда сквозь расписанные причудливым узором окна уютных, теплых ломов прокрадывается темнота, а во дворе тревожно завывает вьюга, Снежная королева умчала маленького Кая в свои ледяные владения и превратила его доброе отзывчивое сердце в осколок льдинки. Через множество испытаний пришлось пройти верной Герде, чтобы добраться до чертогов Снежной королевы и спасти мальчика, освободить его из ледового плена, где царят душевный холод и безразличие.",
 "f-wd751842": "Фильм поставлен по одноименной повести Ванды Василевской и рассказывает о героической борьбе советских патриотов, жителей украинского села Нова Лебедивка, против гитлеровских оккупантов.",
 "f-wd2628313": "Фильм снят во время войны по повести Льва Славина «Мои земляки». Искренний и правдивый рассказ о дружбе Аркадия Дзюбина, неунывающего, лихого и бедового парня из Одессы, и Саши Свинцова - «Саши с Уралмаша».",
 "f-wd2388260": "Жил-был в Царь-столице грозный царь. Задумал он взять в жены Царь-девицу и послал за нею Иванушку, крестьянского сына. Вовек бы тому не добраться до красавицы, если б не волшебный помощник, сказочный Конек-Горбунок…",
 "f-wd1978763": "Бедный студент Родион Раскольников идёт на преступление, за которым неизбежно следуют муки совести: его душа, отягощённая грехом убийства, мечется между верой и безверием, надеждой и отчаянием. Расследование сыщика Порфирия Петровича в конечном итоге выводит следствие на Раскольникова, но ещё до знакомства со следователем Родион встречает настоящую любовь. Она поможет ему прийти к покаянию.",
 "f-wd63985408": "История двух молодых женщин-фронтовичек, которые возвращаются в послевоенный Ленинград и пытаются обрести новую мирную жизнь, когда и вокруг, и главное, внутри них — руины.",
 "f-wd1218234": "Было у купца три дочери. Отправляясь в заморское странствие, пообещал он им привезти подарки, какие они пожелают. Две старшие попросили себе тканей и красивых безделушек. И лишь меньшая, любимая, Алена, заказала отцу чудо диковинное, невиданное — аленький цветочек, который видела она во сне.  Рос тот цветок в далеких краях, во владениях лесного чудовища. Отправился купец в дорогу. Цветок он нашел, однако оказался пленником чудовища. Вслед за отцом собралась в путь Алена. Ее самопожертвование было вознаграждено: ведь чудищем лесным был заколдованный прекрасный принц.  Красавица полюбила его за доброе сердце и освободила от чар злой волшебницы. И сыграли они веселую свадьбу.",
 "f-wd4177789": "Действие происходит в глубоком тылу Германии. Для улучшения характеристик противотанковых орудий, немцы использовали захваченные трофейные танки Красной Армии в качестве «живых» мишеней. Экипажи машин укомплектовывали военнопленными танкистами и гражданскими лицами из концлагерей. Фильм повествует о бегстве из плена одного из таких экипажей на танке Т-34.",
 "f-wd18621595": "Тщеславный тролль Орм давно мечтает о лаврах героя, и наконец получает этот шанс: северный ветер грозит миру вечной зимой и похищает Марибель. Рука принцессы и королевство троллей достанутся тому, кто вызволит её из снежного плена. Однажды Орм победил зиму с помощью друзей, теперь он хочет действовать в одиночку. На нём доспехи из сковородок, за ним — отряд трусливых троллей, а впереди — опасный путь к замку Снежной королевы. Но, к счастью, друзья не помнят обид: храбрая Герда, застенчивый Кай, удалая Альфида и весёлая Лута не бросят Орма в беде. А значит их ждут невероятные приключения!",
 "f-wd4367638": "Маленькая Наташа вышла из дома и потерялась в большом городе. В её судьбе приняли участие все, кого она встретила в своём увлекательном, полном весёлых приключений путешествии. Всё, конечно, закончилось хорошо. А пока Наташа блуждала по городу, она приобрела много друзей и среди взрослых и среди детей.",
 "f-wd4508565": "Действие фильма происходит перед революцией. Судьба загоняет в беспросветную нищету официанта столичного ресторана Скороходова. На фронте гибнет его сын, умирает жена, дочь исключают из гимназии за неуплату. Одну из комнат своей убогой квартирки Скороходов решает сдать скромному молодому человеку — курьеру военно-промышленного комитета Соколину. Квартирант и девушка, полюбив друг друга, решают пожениться.",
 "f-wd13403118": "Фильм посвящен первым шагам человечества на пути освоения космоса и непосредственно судьбе первого космонавта Ю. А. Гагарина. Основной лейтмотив - борьба за право быть первым: соревнование в первом отряде космонавтов; конкуренция технологий в ракетостроении; противостояние сверхдержав - СССР и США.  В первый отряд космонавтов отбирали из трёх тысяч летчиков-истребителей по всей стране. В легендарную двадцатку попали лучшие из лучших. Кто из них полетит первым, не знал никто. На этом пути пришлось бороться не только с земным притяжением…",
 "f-wd133543": "Автобиографическая повесть, события которой происходят в 1947 году в небольшом шахтерском городке Сучан, более похожем на трудовой лагерь, нацеленный только на одно - дать стране как можно больше «черного золота».  Подростки Валерка и Галия живут в одном бараке. Они не столько мечтают о будущей счастливой жизни, сколько просто любят все, к чему привык глаз в этом Богом забытом городишке...",
 "f-wd383034": "События фильма разворачиваются накануне вывода советских войск из Афганистана с 13 по 16 мая 1988 года.  И, казалось бы, можно уже не волноваться за судьбу наших ребят, но... война продолжается. В подразделение десантников, которым командует майор Бандура, направляется сын высокопоставленного военного. Причина его прибытия накануне вывода войск понятна всем: парню необходимо успеть \"поучаствовать\" в боевых действиях и заработать награды.",
 "f-wd1980182": "Фильм по мотивам военных рассказов Юрия Германа.  1944-й год. Вторая мировая война. Полк морской авиации базируется на небольшом аэродроме. Для лётчиков это одновременно - и фронт, и тыл. Они выполняют боевые задания и возвращаются к своим семьям. Но каждый вылет может оказаться последним.",
 "f-wd3220514": "Западная Белоруссия находится под властью панской Польши. Панас лишается всего имущества и окончательно теряет надежду на Бога. Герой приходит в город, нанимается на угольную шахту и вскоре попадет в тюрьму за участие в рабочем движении. Так начинается путь пролетария-революционера, бывшего крестьянина, убедившегося «на своей шкуре» в том, что и в деревне и в городе бедняку за свою жизнь надо бороться.",
 "f-wd4340787": "Первый фильм тетралогии о судьбе опытного разведчика, сына русского эмигранта графа Тульева. Резидент должен добыть сведения о разработках в атомной промышленности, но чекисты нападают на его след — и он допускает роковую ошибку...",
 "f-wd1655330": "Легенды 60-х годов XX века, изложенные в двадцати эпизодах.",
 "f-wd123742": "Прощальную вечеринку уезжающего в Японию Роба прерывает громогласный рык — нечто напало на Нью-Йорк, сея панику, разрушения и пожирая людей. Армия бессильна против гигантского монстра, Манхэттен объявлен закрытой зоной, но где-то неподалеку от Центрального парка в беду попала девушка Роба.",
 "f-wd390052": "Том Рипли знал, что рано или поздно он пробьется наверх. Однажды после случайного знакомства один из богатейших людей Америки дает Тому поручение съездить в Италию и убедить его сына, транжирящего деньги в Европе, вернуться в Штаты.",
 "f-wd131686066": "На США летит межконтинентальная ядерная ракета, неизвестно кем запущенная. До поражения цели осталось 20 минут, военные и чиновники в Белом доме пытаются справиться с кризисом.",
 "f-wd6477009": "Шестнадцатилетняя Элис Палмер тонет, купаясь возле местной дамбы. Полиция выносит заключение, что это был несчастный случай, семья хоронит ее тело. Но вскоре безутешные родители начинают ощущать странное присутствие в доме и слышать звуки из комнаты покойной.",
 "f-wd3483832": "Отец и дочь-тинейджер получили работу по реставрации дома. Они решаются переночевать в старом жилище, а рано с утра приступить к работе. Но все пошло не так, когда девушка ночью стала слышать странные звуки с верхних этажей…",
 "f-wd123477948": "Прожив несколько лет в США, мужчина возвращается в родной австралийский город на побережье, где собирается купить дом, когда-то принадлежавший его семье. Вместе с сыном-подростком он отправляется поплавать на досках, но сталкивается с сопротивлением банды сёрферов, считающих, что этот пляж — только для местных. Мужчина сдаваться не собирается и вступает с ними в жестокое противостояние.",
 "f-wd1198219": "Молодой человек Витек пытается найти себя — то заключает сделку с госбезопасностью, то вливается в студенческое движение, то погружается в религию. Символом его метаний становится поезд, на который он все время опаздывает.\r На эту политическую канву накладывается его любовные искания. Он безрезультатно ищет свою любовь и сам не замечает, как предает любимых женщин.",
 "f-wd1093026": "Священник маленького городка повесился на кладбище и этот страшный грех открыл Дверь из Преисподней. Встав из могил, зомби начинают истреблять жителей. Души мертвецов не могут найти покоя, армия мертвецов растет. Врата можно закрыть только в течение 48 часов, до начала Дня Всех Святых... Журналист Петер и девушка-медиум Мери отправляются в Данвич, чтобы остановить смерть...",
 "f-wd3718974": "Компания старых приятелей, достойно выдержавших испытание национальной охотой, вновь собирается вместе — на сей раз для того, чтобы культурно отдохнуть под видом рыбной ловли. В разгар веселья друзья узнают, что, сами того не ведая, пересекли государственную границу и отдыхают уже в Финляндии. После поспешного возвращения выясняется, что по ту сторону Финского залива осталось очень много водки.",
 "f-wd919444": "Огромный счет в банке, красивые женщины, яхта, ласковое море - это сладкая жизнь, которую Том Рипли так хочет иметь и которая у Филиппа Гринлифа уже есть. Филипп даже не подозревает, на что готов пойти Том, чтобы сделать его жизнь своей. Сначала убийство, потом подделка документов, подписи, голоса... И бедный авантюрист превращается в миллионера. Но даже самая искусная подделка всегда остается лишь копией, даже если над ней трудился талантливый мистер Рипли.",
 "f-wd822946": "Париж, 1968 год — демонстрации студентов, баррикады на улицах, в воздухе пахнет революцией. Но у трёх молодых людей — своя реальность, свой мир — мир кино. Дни и ночи напролёт они смотрят фильмы и не выходят из дома... Кино стало их жизнью. Сначала это просто увлечение, потом — сложная паутина психологических и сексуальных отношений. Между тем, беспорядки на улицах Парижа достигают своей кульминации...",
 "f-wd753899": "Скотт Пилигрим нашёл девушку своей мечты. Но на его пути стоит более сложная задача: чтобы встречаться с ней, Скотту придётся победить её 7-ых бывших и очень злых парней.",
 "f-wd55080292": "Майлз небезосновательно считает себя неудачником: девушка бросила, а сам он работает в заштатной конторе разработчиком мобильных игр. Единственная отдушина в жизни парня — интернет-троллинг. Каждый вечер он провоцирует кого-нибудь в сети и, хорошенько поругавшись, спокойно засыпает. Однажды Майлз хамит очередному незнакомцу на сайте, где транслируются жестокие игры на выживание, и вскоре, вычислив местоположение нашего диванного героя по IP, в его дом вламывается группа отморозков. Теперь к рукам Майлза прибиты два пистолета, а сам он выставлен на поединок с психопаткой по имени Никс — безжалостной чемпионкой этих подпольных игрищ.",
 "f-wd15965953": "Скрат в эпической погоне за постоянно ускользающим от него жёлудем, оказывается выброшен в открытый космос, где он устраивает ряд космических происшествий. И теперь над миром ледникового периода нависла угроза. В целях самосохранения Сид, Мэнни, Диего и остальные герои вынуждены покинуть свои дома и отправиться в путешествие навстречу новым загадочным землям и ярким знакомствам.",
 "f-wd18703028": "«Четыре всадника», команда лучших иллюзионистов мира, снова в сборе! Их «магия» стала ещё совершеннее, а враги - опаснее. На сей раз им предстоит спасти свою репутацию и вывести на чистую воду жестокого техномагната.",
 "f-wd925384": "Лондон в наши дни. Мать двенадцатилетнего Куинна случайно пробуждает гигантского огнедышащего дракона от многовекового сна. Двадцать лет спустя. Большая часть планеты находится под властью чудовища и его потомков. Драконы очень умны, им не нравится делить с кем-либо планету. Будучи начальником пожарной охраны, Куинн несет ответственность за ту маленькую группу людей, которым удалось выжить. Ведь в то время, когда все небо залито огнем пожарный — самый главный человек на земле.",
 "f-wd161087": "Капитан Джек Воробей узнаёт, что пришло время расплатиться по старому долгу перед легендарным морским капитаном Дэйви Джонсом — властителем «Летучего голландца». Чтобы избежать вечного рабства на его корабле, Джек отправляется на поиски таинственного Сундука мертвеца, в котором хранится ключ к судьбе Джонса. Тем временем Уилл Тёрнер и Элизабет Суонн оказываются втянуты в опасное путешествие, где им предстоит столкнуться с морскими чудовищами, коварными врагами и непростыми испытаниями, способными навсегда изменить их судьбы.",
 "f-wd179215": "Вторая часть невероятных похождений прославленного археолога и искателя приключений Индианы Джонса. В этот раз бесстрашный доктор Джонс совершит путешествие в сердце Гималаев вместе с ресторанной певичкой Уилли Скотт и своим верным маленьким помощником Коротышкой.Здесь, среди величественных гор, археологу и его спутникам предстоит столкнуться кровавым культом поклонения древней Богине Смерти — Кали.",
 "f-wd1405113": "Интернациональный отряд наемников сопровождает ученого в поисках таинственного бункера, скрытого в глухом лесу в одной из стран Восточной Европы. Добравшись до нужного квадрата, бывалые бойцы без особого труда выходят на искомый объект.  Исследуя объект, отряд обнаруживает страшное существо, которому удалось выжить. Под команду монстра встает множество немецких солдат-зомби, которые умеют только убивать. А у живых остается лишь одна задача: выбраться из этого страшного места! Жаль только, что гитлеровские «живые трупы» с этим категорически не согласны. Военная миссия превращается в настоящую резню, зомби начинают охоту…",
 "f-wd337747": "В сверхсекретном научном центре получили из космоса формулу ДНК, которая была воспроизведена и скрещена с женской. В результате получилась девочка, которая росла не по дням, а по часам. Напуганные результатами эксперимента ученые решают уничтожить подопытное существо, но оно сбегает. Из девушки существо превращается в женщину с очень сексапильной внешностью, которая жаждет размножаться.",
 "f-wd2125739": "Маленький городок в Западной Вирджинии проводит ежегодный фестиваль «Горный человек», посвящённый Хэллоуину. Туда направляется группа студентов колледжа, однако они не подозревают, что шумная костюмированная вечеринка с музыкой и выпивкой обернётся для них кровавым кошмаром — на фестиваль направляется семья горных каннибалов.",
 "f-wd4424041": "Главные персонажи этой истории времён гражданской войны — красноармеец Некрасов, по приказу ставший фронтовым кинооператором, и его помощник Карякин, бывший командир роты, бдительно опекающий беспомощного и, по его мнению, не вполне надёжного «фотографа». В конце концов отчаянный спорщик Карякин полюбит фронтового товарища — да только от вражеской пули не сможет уберечь...",
 "f-wd96942519": "Социально-философская драма. Героиня фильма живет в грузинской глубинке. Она замужем за лидером религиозной общины иеговистов, терроризируемой экстремистами. Но и внутри общины женщина — тоже объект угнетения и подавления, ведь мир секты утрирует общий принцип мужского доминирования. Встреча героини с местным полицейским, «стражем порядка», перерастает в грубое сексуальное и одновременно социальное насилие...",
 "f-wd275432": "Ранго - хамелеон, который живет в террариуме и считает себя героем, которому, к сожалению, никак не удается проявить свое бесстрашие. Но когда он внезапно оказывается в городке Грязь, у него появляется такая возможность. Ранго провозглашает себя борцом за справедливость и начинает вести себя как шериф на Диком Западе. Он еще не знает, что быть «хорошим парнем» в этих краях не самая завидная участь...",
 "f-wd15270648": "В Тридевятом царстве, где живут наши герои — тишь, да благодать. Иван женился на Василисе, и «жили они долго и счастливо», да не тут-то было. Иван целыми днями пропадает с Волком на службе — укрепляет рубежи и оборонную мощь, мечтает перевести стрелки часов на семь часов назад, чтобы меньше спать, и больше работать. А Василисе — скучно, как всем девушкам, ей хочется романтики, ну, такой, как в сказках. И тогда она решает организовать своё похищение... Однако, когда такое бывало, что в сказках всё получалось так, как задумывалось?",
 "f-wd18405973": "В надежде сорвать большой куш Наташин отчим идет на финансовую авантюру, чем подставляет своих партнеров по бизнесу. Без лишних слов те устраивают на него покушение. Вся семья скорбит по Борису Ивановичу… а он в гробу все это видел. Ему бы три дня пролежать и похороны пережить, а там родные откопают и можно спать спокойно. И все идет по плану уцелевшего отчима, пока проститься с ним не приезжает боевой товарищ. Рубаха-парень Витька Каравай мгновенно покоряет всю семью, перетягивая общее внимание на себя. Задетый за живое, покойник заставляет родных устроить роскошные поминки с участием Светлакова…",
 "f-wd470891": "В 2032 году в крио-тюрьме после 35-летней заморозки пробуждается один из самых опасных преступников Саймон Феникс и решает взять приступом спокойный, свободный от всякого насилия Лос-Анджелес. Неспособные справиться с жестокими повадками 1990-х годов, свойственными Фениксу, официальные власти ищут полицейского тех лет, который смог бы одержать верх над преступником 90-х. Для этого они размораживают сержанта Джона Спартана, несправедливо осужденного на срок в крио-тюрьме за его последнюю схватку с Фениксом.",
 "f-wd14704171": "Хэйзел больна раком. Несмотря на то, что болезнь временно отступила, девушка не чувствует ни капли радости. Она ходит в группу поддержки, где однажды знакомится с Августом Уотерсом и моментально влюбляется в него. Август и Хэйзел отправляются в полное страсти и жизни путешествие, которое лишний раз покажет им, что весь смысл жизни можно найти в любом ее отрезке.",
 "f-wd28369564": "Белокурая чемпионка Тоня Хардинг вот-вот подпишет на дело двух идиотов. На нее начнут охоту папарацци и лучшие агенты ФБР. Но это будет потом, а пока за ней с придыханием следит вся страна. Тоня — гордость нации, без пяти минут член олимпийской сборной по фигурному катанию. Надо лишь избавиться от конкурентки. В ее голове зреет дерзкий план.",
 "f-wd590252": "Снайпер убивает нескольких случайных прохожих. Его находят и арестовывают. Все улики указывают на него. На допросе вместо признания он пишет имя — Джек Ричер. Больше обвиняемый не может ничего сказать, поскольку после избиения заключёнными впадает в кому. Загадочный Джек Ричер появляется незамедлительно. Что теперь будет с убийцей?",
 "f-wd7845294": "Отправляясь в увлекательное приключение, которое заведёт её далеко от привычного ей мира, Розочка объединяет усилия с самым мрачным троллем на свете по имени Цветан для достижения успеха в своей смелой миссии спасти её друзей из тисков зловещих бергенов и их лидера, короля Хрящ Старший. Невероятные приключения Розочки проверят её силу, покажут её истинную суть и бросят вызов её способности ударяться в пение в любой момент.",
 "f-wd932814": "История молодой женщины, чудом выжившей в автокатастрофе, но потерявшей мужа — композитора и пятилетнюю дочь, и это не столько повествование о возвращении к жизни, сколько метафорическая притча об избавлении от власти губительных чувств. Преодолеть трагедию — значит в каком-то смысле обрести свободу: от прошлого, от любви. Но такая свобода опустошает, лишает желания жить. Оно возвращается лишь с приходом новой любви…",
 "f-wd192409": "Действие происходит в Новом Орлеане. Ди-джей Зак, переживающий полосу неудач, соглашается перегнать ворованный автомобиль, чтобы быстро заработать немного денег. К сожалению, его останавливает полиция. В багажнике его машины находят труп. Он попадает в тюрьму.Сутенер Джек, подставленный своим врагом, тоже попадает в руки закона и оказывается в одной камере с Заком. Вскоре в их маленькой камере появляется Роберто, приятный, смешной итальянец, знающий всего несколько фраз по-английски и обожающий американские фильмы.В конце концов все трое совершают побег и оказываются в луизианских болотах, где теряются, голодают и падают с ног от усталости…",
 "f-wd55657380": "Марк — одинокий пятидесятидвухлетний художник, живущий за границей русский эмигрант. Он возвращается на родину, навестить отца, которого не видел много лет. Пребывание дома открывает перед Марком двери его «детских шкафов», полных скелетов прошлого, дает ответы на вопросы, которые мучали его на протяжении всей жизни.",
 "f-wd54674414": "Семеро друзей, собравшись в загородном доме, в шутку начинают игру — участники должны зачитывать вслух все приходящие им сообщения, а на звонки отвечать только по громкой связи. Они и представить себе не могут, какие удивительные откровения им предстоит сделать друг о друге.",
 "f-wd25820974": "Артур — мастер своего дела. Работая только с крупными должниками, он находит всю их подноготную и эффективно использует против них. Он никогда не прибегает к банальным методам, его конек — психологическая атака. Артур умеет виртуозно перевоплощаться, сбивать с толку, выводить из равновесия, и так допекать своих клиентов, что они готовы вернуть все, только бы никогда больше не слышать его голос. Но однажды Артур сам становится мишенью: в сети появляется скандальное видео с его участием, и от него мгновенно отворачиваются друзья и коллеги. Под угрозой оказывается не только его репутация, но и жизнь… Теперь у коллектора есть всего одна ночь чтобы найти того, кто загнал его в угол.",
 "f-wd127698549": "Июнь 1944 года. Высадка в Нормандии, крупнейшая в истории морская десантная операция, уже подготовлена, и любая задержка грозит тем, что немецкая разведка раскроет планы союзников. Главному метеорологу Великобритании Джеймсу Стэггу предстоит убедить все командование союзных сил во главе с генералом Дуайтом Эйзенхауэром довериться его нестандартным методам и изменить планы операции. У ученых остается лишь 72 часа на точный прогноз сразу двух надвигающихся штормов, но от этого зависит судьба всего Западного фронта.",
 "f-wd137708148": "Ребекка Оуэнс, выпускница медицинского вуза, устраивается на ночную работу в морг на должность ассистента патологоанатома. В первую же смену она вскрывает в морге демона, который пытается завладеть ее душой. Чтобы пережить ночь, ей придется раскрыть жуткие секреты своего загадочного наставника, преодолеть собственные страхи и пройти все круги ада.",
 "f-wd111170246": "В канун Рождества преступники берут в заложники состоятельную семью, чтобы получить их деньги. Незадолго до этого захваченные родители подарили дочери рацию, по которой можно связаться с Сантой. Девочка вызывает подкрепление в его лице, чтобы проучить захватчиков.",
 "f-wd123185887": "Молодая стриптизёрша из Бруклина внезапно выходит замуж за сына русского олигарха. Узнав об этом, родители парня тотчас вылетают из Москвы в Нью-Йорк. Они готовы на всё, лишь бы расстроить брак.",
 "f-wd28466353": "Звездные блогеры рунета: Саша Спилберг, Ивангай и Марьяна Ро были «взломаны» неизвестным вирусом и перенеслись на «рабочие столы» своих компьютеров в виде анимационных героев. Под угрозой отношения Вани и Марьяны, карьера Саши и аккаунты миллионов их фанатов. Кто вторгся в их аккаунты и завладел всеми данными? Как вернуться в привычную онлайн-жизнь? Пошел обратный отсчет — ребята должны вырваться из цифровой ловушки.",
 "f-wd3280057": "Триш Дженнер воспитывает сына-подростка, которого она назвала Дэрри — в честь брата, погибшего в когтях чудовищного монстра. По ночам Триш видит один и тот же кошмар, в котором её сына ждёт та же участь, что и брата. Ведь каждую 23-ю весну просыпается зловещий монстр Джиперс Криперс и 23 дня, распространяя ужас и страх, рыскает по свету в поисках новых жертв. Время пробуждения приближается…",
 "f-wd927919": "Голос тайного ангела пел песни Кристине. Только она не знала, что ее тайный ангел — всего лишь Призрак — гений, который жил в подвале театра и наводил ужас на всех артистов, которые там работали.",
 "f-wd20762668": "Когда-то Махавир Сингх Пхогат был чемпионом Индии по борьбе. По причине бедности он был вынужден бросить спорт, но поклялся воспитать сына, который станет в будущем олимпийским чемпионом. Но вот досада — у них с женой родились четыре дочки. Отец сначала отчаялся, но потом, увидев, что подросшие девчонки поколачивают одноклассников, решил всё же сделать из них спортсменок.",
 "f-wd107166862": "1919 год. Судьба сталкивает юного идеалиста Осю с турецко-подданным аферистом Ибрагимом Бендером. И никогда бы честный Ося не связался с таким бессовестным и хитроумным мошенником, если бы их не объединила невероятно опасная авантюра — охота за царской реликвией, драгоценным жезлом, заполучить который также не прочь местные бандиты и белые офицеры. В череде головокружительных приключений Ося вынужден учиться у Ибрагима обаятельной лести, деликатному обману, пленительному шантажу и… грубой силе. И все это — будучи влюбленным в самую чистую девушку города! И, кажется, еще в одну — роковую иностранную красотку. Так начинает складываться портрет легендарного великого комбинатора и любимца женщин Остапа Бендера-Задунайского.",
 "f-wd4240049": "Сложные морально-нравственные проблемы, которые семейная жизнь ставит перед своими героями, делают фильм созвучным не только времени создания повести. В киноверсии, как и в ее первооснове, сталкиваются разные временные пласты, она остросюжетна и динамична, интересна и своеобразна по кинематографическому решению.",
 "f-wd112083510": "Это вторая часть серии фильмов «Пушпа» и продолжение фильма 2021 года «Пушпа: Восхождение». Столкновение продолжается: Пушпа и Бханвар Сингх продолжают свое соперничество в этом эпическом завершении двухсерийной боевика.",
 "f-wd115053037": "В последние дни Второй мировой камикадзе Коити Сикисима посадил самолёт на острове Одо, где располагалась ремонтная база императорской армии Японии. В тот же вечер на них напал непонятно откуда взявшийся огромный ящер Годзилла — именно так называли его местные. Коити возвращается в разрушенный бомбардировками Токио (родители погибли, от дома остались одни обломки) и пытается жить дальше. К нему прибивается тоже потерявшая семью девушка с младенцем, которого она спасла во время воздушного налёта. Время идёт, жизнь налаживается, Коити работает в команде по обезвреживанию мин в Токийском заливе, и однажды их хлипкий деревянный катер сталкивается с Годзиллой, который после ядерных испытаний на атолле Бикини стал ещё больше и ещё свирепее.",
 "f-wd124636001": "Десять друзей, входящих в состав группы «Парни из Манджуммела», отправляются в путешествие по Кодайканалу. На обратном пути один из них вспоминает о пещерах Гуна, где снимался знаменитый одноименный фильм. Друзья добираются туда и, несмотря на предупреждающие знаки, проникают в запретную зону. Там они очень весело проводят время, пока один из них не проваливается в яму, глубину которой сложно измерить. Парни пытаются докричаться до него, но у них ничего не выходит. Тогда они обращаются за помощью к местным жителям, лесникам и полицейским, но у всех один ответ: из этой ямы пока еще никто не выбирался живым.",
 "f-wd134972728": "Таинственная девушка по имени Чандра появляется в Карнатаке, скрывая многовековую тайну. Под маской обычной работницы она - бессмертная Якши, древнее существо с сверхъестественными способностями. Когда она сталкивается с бандой торговцев органами, её прошлое настигает её. Но настоящая битва только начинается - правительственные силы, мутировавшие якши и древние существа угрожают раскрыть её существование миру. Первая глава эпической саги о скрытом мире мифических существ, живущих среди людей.",
 "f-wd123119123": "Жизнь майора Мукунда Варадараджана разворачивается на фоне операции «Казипатри» в Шопиане, Кашмир, которая состоялась в 2014 году.",
 "f-wd126734383": "Гангстер Марко и его могущественная семья Адат, которые заправляют золотым бизнесом в мафиозных кругах Кералы, сталкиваются с угрозой извне.",
 "f-wd124445827": "В керальском городе Аллеппи живёт простой булочник Джон вместе с пятилетней дочкой Кхуши и помощником Джеки. Отец и дочка души друг в друге не чают, им хорошо в своём уютном мирке, куда они никого не пускают. Но однажды стычка с местными хулиганами оборачивается для них неприятностями. Ниточки этой стычки тянутся в прошлое, где у Джона всё было другим — имя, работа, семья. Из прошлого в настоящее врывается и враг Джона, который по-прежнему жаждет мщения. Герой понимает, что прятаться бессмысленно, и единственный шанс спасти себя и дочь — самому нанести удар. Ремейк тамильского фильма \"Theri\" 2016 года.",
 "f-wd117210104": "Плимут, штат Массачусетс. Давка в торговом центре в Чёрную пятницу, совпавшую с Днём благодарения — празднике, зародившемся в этом городке, — унесла жизни нескольких человек. Год спустя, надев маску первого местного губернатора Джона Карвера и украв из музея его топор, неизвестный начинает охоту на виновных в той трагедии.",
 "f-wd130323320": "Арджун Саркар, один из лучших офицеров ХИТ из Вишакхапатнама, направлен в Джамму и Кашмир для расследования кровавых убийств.",
 "f-wd106261265": "С самого детства Робби Уильямс чувствовал себя немного диким. Стремясь доказать своему отцу, чего он стоит, Робби решает рискнуть всем и начать музыкальную карьеру. Однако ни роскошная жизнь миллионера, ни стадионы поклонников не меняют то, как он себя видит.",
 "f-wd129900370": "Девушка готова пойти на всё, чтобы защитить брата.",
 "f-wd126285104": "2000 год. Кришна и Васудха влюблены друг в друга, но парня обвиняют в убийстве и сажают в тюрьму. 22 года спустя Кришна выходит на свободу. Он встречается с Васудхой, которая давно замужем.",
 "f-wd1076823": "Сверхъестественные способности, появившиеся у Рохита благодаря инопланетному пришельцу, также появились у его сына Криша. Но сам Рохит остался в плену у злого доктора Ария. Поэтому Криша увезла в далекое село его бабушка.",
 "f-wd1203252": "Дону уже принадлежит вся Азия. Однако ему этого мало: он задумал покорить Европу и решил начать с Берлина. Как обычно на его пути стоит спецотряд полиции и многочисленные конкуренты.",
 "f-wd617395": "Индия, 1938 год. Восьмилетняя девочка узнает, что она стала вдовой. Когда-то ее выдали замуж \"впрок\" за незнакомого взрослого мужчину и оставили в отцовском доме. Теперь согласно святым законам у нее есть три пути: сгореть с мужем на погребальном костре, выйти замуж за его младшего брата или стать неприкасаемой и до конца своих дней жить в ашраме - приюте для вдов при храме, на берегу большой реки...",
 "f-wd19833751": "Для жестокого и умного бутлегера наступают тяжелые времена, когда храбрый полицейский начинает преследовать его.",
 "f-wd3090065": "Неизвестная девушка Решма неожиданно становится секс-символом в кино и приобретает новое имя - Силк. На различных этапах своей жизни Силк разделяет страсть, любовь, ненависть с тремя разными мужчинами. Она любит человека, который ее жаждет, относится с материнскими чувствами к человеку, который ее любит, и заканчивает тем, что очаровывает того самого человека, который ее ненавидит. Но Силк привыкла жить по своим правилам и всегда оставаться собой, что нравится далеко не всем...",
 "f-wd19824742": "Братья Арджун и Рахул должны вернуться в родительский дом по просьбе 90-летнего дедушки. Старик хочет провести последние дни своей жизни рядом с внуками. Арджун и Рахул постоянно оказываются в комичных ситуациях из-за того, что не могут найти рациональных объяснений происходящему. И когда братья влюбляются в одну и ту же девушку, между ними начинается настоящая война. Они не могут справиться со своими эмоциями, и это становится причиной полного разлада в семейных отношениях.",
 "f-wd3073136": "Во время беспорядков пропал младший брат Аман. Его не было среди погибших, но и все попытки разыскать его через телевидение и прессу оканчивались безрезультатно. И хотя в течение прошедших семи лет Физа с матерью продолжали надеяться, что он жив, в глубине души они уже смирились с его смертью. Но однажды Физа из окна автомашины отчётливо увидела в толпе его лицо...",
 "f-wd2036518": "События происходят в Калькутте в 1962 году, когда маленькая Лолита приезжает жить в семью своего дяди, где судьба сталкивает ее с мальчиком Шекхаром, способным музыкантом, сыном влиятельного бизнесмена. С этого времени они разделяют радости и печали. Незаметно для них их дружба перерастает в любовь, которую они даже не замечают. И только появление в их жизни нового человека, Гириша, раскрывает им настоящие чувства друг к другу.",
 "f-wd115673833": "История семейной пары Белли и Боммана, которые живут рядом с живописным лесом, являющимся естественной средой обитания для огромного количества животных. Однажды судьба сводит Белли и Боммана с осиротевшим слоненком Рагху, о котором главные герои решают начать заботиться. Тяжело и неустанно работая, чтобы Рагху выжил, семейная пара быстро осознает, что уход за настоящим слоном — сложнейший вызов. Не собираясь сдаваться перед трудностями и неприятностями, главные герои ежедневно работают над тем, чтобы Рагху приспосабливался к жизни с людьми и не испытывал дискомфорта.",
 "f-wd1784272": "Рассказ о человеке, вызвавшем армейский бунт и, как следствие, первую индийскую войну за независимость. В основу истории были положены реальные факты, дошедшие до нас из описаний событий далекого прошлого. Забытый герой Мангал Пандей, чье имя стало символом восстания против британского правления и британский капитан Уильям Гордон — главные герои саги.  Воин-брамин Мангал дружил со своим командиром, Уильямом, после того, как спас его жизнь на Афганской войне. Их дружба казалась прочной, пока не произошли события, вызвавшие сражение за независимость.",
 "f-wd29467155": "Наина Матур всегда хотела стать учителем, но у неё синдром Туретта. Ученики откровенно издеваются над женщиной, а директора школ не хотят брать на работу. И даже собственная мать не верит, что Наина сможет стать учительницей. Но судьба даёт девушке шанс — она получает работу мечты в элитной школе. Вот только класс, который ей достался, состоит из хулиганов и мажоров, и им учительница с тиком как раз кстати — ведь это новый объект для насмешек. Как превратить свою слабость в силу? Да просто ничего не бояться, и особенно — смеяться над собой!",
 "f-wd58619": "Не желая поступиться собственной карьерой, киноактриса Киран уходит от мужа, оставив ему на воспитание трехлетнего сына. Однако, проходит время, вершина славы достигнута и, почувствовав одиночество, Киран вспоминает, что у нее есть семья...",
 "f-wd2617038": "Команда мошенников, состоящая из профессионального жулика, автомобильного эксперта, опытной соблазнительницы, волшебника-иллюзиониста, специалиста по взрывчатым веществам, компьютерного хакера и актера, умеющего до полной неузнаваемости изменять свою внешность, планирует совершить грандиозное ограбление. На кону 100 миллионов долларов. Их цель — поезд с золотыми монетами на борту, движущийся из России в Румынию.",
 "f-wd3635561": "Фильм о несчастной любви Шеры и красавицы Решмы, детей двух враждующих семейств раджпутов. Узнав о любви Шеры к Решме, его брат Чхоту выполняет приказ своего отца и убивает отца девушки и ее брата. Не в силах вынести горя овдовевшей прямо на свадьбе невесты, Шера убивает своего отца, полагая, что это он нажал на курок. Спасая возлюбленного от горя и безумия, Решма, пожертвовав собой, выходит замуж за Чхоту…",
 "f-wd1740519": "История талантливой, музыкально одаренной девушки Энни, которая живет, окруженная безмолвием своих глухонемых родителей. Она очень любит их, для нее они самые лучшие на свете, но всю свою жизнь она ждет все же, когда рухнет стена молчания. Она ждет и надеется, что родители смогут назвать ее по имени. И именно это спасает ее в трудную минуту. Ни плач ее сынишки, ни мольбы любимого мужа, а неумело произнесенные звуки, которые какая-то добрая сила сложила в имя девушки: «Э-н-н-и».",
 "f-wd96631747": "Как это принято в некоторых районах Индии, мальчик и девочка были помолвлены, но парень не спешил жениться, вырос и уехал. А вернувшись в родные края, обнаружил, что там свирепствует злобный ночной демон, убивающий только мужчин. Местные считают, что его суженая обернулась мифической сущностью и таким кровожадным способом скорбит о своей потере.",
 "f-wd56278247": "Главный герой фильма – невероятно целеустремлённый и честолюбивый парень по имени Риши. Однажды он решает переехать в Соединённые Штаты для того, чтобы там заработать себе многомиллионное состояние. Риши прилагает массу усилий для достижения своей цели. Чтобы заработать все эти деньги, молодой человек был вынужден переступить через самых разных людей, которые какое-то время даже оказывали ему помощь. Ему пришлось изменить своим принципам, которых он всегда придерживался, ещё находясь дома, в Индии. Проходит некоторое время, и Риши вдруг решает вернуться на родину – туда, где он бы вряд ли смог достичь такого головокружительного успеха…",
 "f-wd130484591": "Уличный авантюрист пробивается в криминальный мир и становится лидером крупнейшей сети азартных игр в стране.",
 "f-wd107016855": "Инспектор Виджай Пракаш всегда любил купаться в лучах славы. Быстро набирая популярность среди газетчиков, он тщетно пытается очистить репутацию своего отца-шпиона, который был обвинён в предательстве. Однажды Виджай получает задание найти человека, укравшего секретный",
 "f-wd86753703": "Сестра главного героя фильма Каалияна недавно изменила свою жизнь, выйдя замуж за молодого человека. Она должна была получить разрешение со стороны своего брата, но не сделала этого. Практически сразу после того, как их брак был оформлен официально, девушка покинула родные места и отправилась жить в Колкату. Ей ещё не скоро удастся обосноваться на новом месте, ведь сразу после переезда она начинает получать угрозы от неизвестных. И когда ситуация окончательно выходит из-под контроля, ей на помощь приходит брат Каалиян, который ни за что не бросит родственников в беде. Сможет ли он разобраться с негодяями, угрожающими его сестре?",
 "f-wd20002304": "Том Бренд — миллиардер-трудоголик с чудинкой. Он с головой погружен в работу и немного выпал из семейной жизни — даже подарок дочери он покупает в последний момент. Ребекка мечтает о настоящем коте, и как бы Том ни презирал животных, он отправляется в зоомагазин, где выбирает самого роскошного кота по кличке Мистер Пушистые Штаны. В спешке на праздник дочери Том попадает в аварию, а очнувшись, обнаруживает себя в теле этого самого кота. Пока Том-человек отсыпается в больнице, Том-Пушистые Штаны вынужден на собственной шкуре испытать все прелести кошачьей жизни и вернуть любовь семьи, чтобы не остаться навсегда в роли питомца. Благо, жена и дочь принимают кота как родного. Но как заставить их разглядеть в Мистере Пушистые Штаны раскаявшегося отца семейства?",
 "f-wd24238536": "Рохан Бхатнагар — простой парень, зарабатывающий на жизнь дублированием мультфильмов. Однажды он знакомится с красавицей Суприей, в которую сразу же влюбляется. Молодых людей объединяет одна особенность — они оба слепые и смотрят на мир лишь через свой разум. Несмотря на это, они всё же находят друг в друге утешение и взаимное притяжение. Влюблённые женятся и строят планы на совместное будущее, даже не подозревая о том, что впереди их ждёт самый настоящий ад в лице влиятельных братьев Шеллар…",
 "f-wd1624299": "Кама Сутра — история любви. Индия, XVI-й век. Маленькая девочка Майя, дочь танцовщицы, живет при дворце магараджи. Ей разрешают донашивать старую одежду принцессы Тары, посещать уроки танцев и слушать лекции о любви по древней книге Кама Сутра.  Проходят годы, и девочки становятся прелестными девушками, за принцессу Тару сватается прекрасный принц Радж Сингх. Но под жарким солнцем Индии любовь не признает сословных различий.  У одной соперницы есть титул и власть, а у другой лишь красота и непревзойденное искусство обольщения. Чем закончится этот изысканный и жестокий поединок?",
 "f-wd797679": "В семью только что скончавшегося Лоренца Лёвенхьельма, который воспитал в истово протестантском духе двух своих дочерей — Мартину и Филиппу, названных так в честь Мартина Лютера и его соратника Филиппа Меланхтона, приезжает из Франции в качестве домоправительницы женщина по имени Бабетта.\r На самом-то деле, она была вынуждена бросить всё и сбежать из Парижа, охваченного революцией 1871 года, захватив с собой только лотерейный билет, который ежегодно проверял её друг, пока не сообщил через 14 лет, что Бабетта выиграла солидную сумму — 10 тысяч франков. Решив вернуться на родину, Бабетта захотела на прощание отблагодарить сестер за их добросердечность и великодушие…",
 "f-wd494871": "Никому не дано нарушить смену времен года, когда вначале все рождается, затем растет, а потом угасает. Ход жизни неподвластен даже двум монахам, живущим в плавучей хижине на озере, окруженном горами. По мере наступления времени года их души наполняются энергией, что ведет как к чувству одухотворенности, так и к трагедии. Что еще важно, они не могут вырваться из круга жизни, желаний, страданий и страстей, которым подвержены все из нас. Под строгим взглядом Старого Монаха Молодой Монах познает потерю невинности, когда игра становится жестокой…, познает любовь, когда в их замкнутом мире появляется женщина…, познает преступную власть зависти и одержимости…, цену искупления, просветление опытом. И хотя одно время года неминуемо сменяет другое, их хижина, подобно колыбели духа, находится между настоящим и будущим…",
 "f-wd339804": "По пути из школы Али, мальчик из бедной семьи, теряет только что взятую из починки единственную пару обуви своей младшей сестры. Это была серьезная оплошность. И дети решают ничего не говорить родителям, а чтобы те ничего не заметили, придумывают маленькую хитрость. Но, как это иногда бывает, невинная затея приводит к неожиданным обстоятельствам.",
 "f-wd954182": "Сорокалетний Антон возвращается в родную Данию, много лет проработав в африканском лагере для беженцев. Долгие годы среди чужого горя научили его никогда не отвечать насилием на насилие. Даже когда местный автомеханик беспричинно избивает Антона, тот сдерживает гнев. Кажется, что конфликт исчерпан, но тут его сын Элиас вместе со своим другом Кристианом решают отомстить за отца.",
 "f-wd20026867": "Дочь Джульетты таинственным образом исчезает. В попытке отыскать ее следы она возвращается в Мадрид и вспоминает свою бурную юность, любовь и страшную трагедию, которая отдалила ее от дочери. Призрак прошлого терзает ее в настоящем.",
 "f-wd1215918": "Недалеко от Японии, в водах океана, просыпается Годзилла, которого все считали мёртвым. Он движется в сторону самого большого острова Японии. Группа телевизионщиков отправляется на остров, где, согласно легендам, живёт Бог, и находит там гигантскую гориллу по имени Конг. Телевизионщики перевозят гориллу в Японию. Кинг Конг сбегает и начинает вести сражение против Годзиллы.",
 "f-wd1129420": "Фауста, девушка из пригорода Лимы, в Перу, скована страхом. И эта боязнь, как гласит местное верование — прямое следствие того, как солдат-проходимец обошелся с ее матерью. Фауста выросла, мать умерла — самое время преодолеть себя. Кроме «болезни» в наследство от матери Фауста получила и «лекарство»: мать научила ее петь, чтобы преодолевать досаду и горе.",
 "f-wd206182": "Китай, 1911 г. Период политической нестабильности и революционных настроений в государстве. На фоне общей неразберихи и неопределённости, некто Сунь Ятсен поднимает восстание и направляет мощь своих войск с одной единственной целью — свергнуть правящую династию Цинь и установить новый, социально направленный режим управления республикой.",
 "f-wd1424099": "Фильм снят по одноименному роману популярной английской писательницы Рут Рэнделл. Главный герой картины, Виктор, из-за ссоры со своей подружкой Еленой, случайно ранит полицейского.  Через 4 года, проведенных в тюрьме он узнает, что тот самый полицейский стал известным баскетболистом, кумиром и героем зрителей с баснословными контрактами да еще и женился на его бывшей подружке Елене.",
 "f-wd1707921": "Тэд - обычный чикагский строитель, страстно мечтающий о невероятных открытиях и опасных приключениях. Однажды его по ошибке принимают за известного археолога и отправляют в Перу на поиски сокровищ инков. Радости Тэда не было предела, но, похоже, она оказалась преждевременной",
 "f-wd53669": "Пепи изнасилована полицейским, который поймал ее за выращивание марихуаны в квартире.  Теперь Пепи намеревается отомстить ему, сделав так, чтобы от него ушла его жена-мазохистка.",
 "f-wd699559": "Полководец, потерявший в одном из жестоких сражений все свое войско, и два вожака шайки грабителей дают клятву быть братьями, сражаться вместе и защищать друг друга. Три воина ставят перед собой масштабную задачу: остановить гражданскую войну и сделать свою страну мирной и процветающей. На пути к этой цели их ждут кровавые сражения, жестокий выбор - пожертвовать несколькими тысячами человек, чтобы спасти сотни тысяч жизней. Трем полководцам предстоит ответить на вопрос - что такое война: защита родной страны от агрессоров или просто возможность грабить и наживаться.",
 "f-wd483761": "Женщина спокойно живёт со своим двадцативосьмилетним сыном, занимаясь знахарством, помогая всем, нуждающимся в округе. Ни с того, ни с сего, её сына обвиняют в зверском убийстве. Матери надо доказать его невиновность или расстаться с ним на долгие года.",
 "f-wd569281": "Владелец IT-компании хочет продать бизнес. Есть только одна проблема: когда-то он придумал фиктивного руководителя, чтобы не быть ответственным за непопулярные решения.  Покупатели настаивают на личной встрече, и владельцу приходится нанять актера-неудачника, который мог бы исполнить роль босса. К своему удивлению актер обнаруживает, что новая роль рискует стать серьезным испытанием для его моральных убеждений.",
 "f-wd10483256": "Тридцать девять скетчей, связанных между собой странной парой друзей — торговцем никому ненужной утварью и его плаксивым товарищем, которые слоняются по городу, наблюдая за причудами окружающих их людей.",
 "f-wd10527185": "В день своего столетнего юбилея, главный герой этой приключенческой комедии покидает через окно дом престарелых, где он провёл уже немало лет. Он не хочет влачить здесь бесцельное существование, ведь вся его жизнь была полна увлекательных приключений. Судьба сводила его со множеством людей оказавших сильно влияние на судьбы целых народов в 20-м веке – Труменом, Сталиным, Франко. Да и сам он, надо сказать, очень сильно повлиял на ход истории, хотя, конечно, и не осознал этого.",
 "f-wd318827": "Бродячие циркачи, шапито, акробаты, жонглеры, фокусники и шуты - театр! А разве вся наша жизнь - не театр, и мы в ней - не актеры?",
 "f-wd976061": "Женатый офицер влюбляется в юную циркачку. Они бегут от бездушного и лицемерного общества, останавливаясь в загородных отелях и на лоне природы, все яснее понимая, что только смерть может соединить их навечно.",
 "f-wd1536123": "Студент Йорен проводит каникулы на ферме своего дяди. В первый день он встречает 17-летнюю Шерстин, которая живет на ферме поблизости. Молодые люди влюбляются друг в друга, но и родственники Шерстин, и отец Йорена против их отношений.",
 "f-wd476941": "Накануне Французской революции в тихой провинции жуткий страх наводит на знатных мерзавцев таинственный разбойник в маске, чьим фирменным знаком стал черный тюльпан. Неуловимый мститель находчив, бесстрашен, благороден и умен, он прекрасный наездник и гений фехтования. Дворянин Жульен - беспечный неженка, глупый и трусливый - совсем на него не похож. Но никто не знает, что есть нечто, крепко связывающее этих двоих.",
 "f-wd1052975": "Хуан — полицейский, пришел наниматься надзирателем в тюрьму. Знакомство с новым рабочим местом оказалось роковым. Он попал в переделку, и ему пришлось прикинуться заключенным, чтобы спасти свою жизнь. Этот шаг поставил его на тонкую грань выживаемости.",
 "f-wd60832907": "Кубинское правительство направляет в Майами своих шпионов для предотвращения терактов, организуемых враждебными группировками США. Но агенты под прикрытием не только успешно исполняют свою миссию, но и оказываются вовлечены в подпольную торговлю кокаином, что грозит мировым скандалом.",
 "f-wd1510064": "В тяжелые послевоенные годы, в деревне, затерянной в сельской Каталонии, мальчик находит в лесу тела мужчины и его сына. Когда власти пытаются повесить вину за их смерть на его отца, мальчик бросается отцу на помощь, начиная расследование. Но этот опыт учит Андре, что в мире взрослых, пронизанном ложью, необходимо быть крайне осторожным. Теперь, чтобы выжить, он предает свои корни, постепенно открывая чудовище, живущее внутри него.",
 "f-wd1329136": "В 40-х годах японское командование в оккупированной Манчжурии создало концентрационный «Лагерь 731». Узники, чаще китайцы, были материалом для испытаний переносимости экстремальных условий, например, холод, высота, а также для испытаний бактериологического оружия. Среди японцев кто сразу, а кто постепенно привыкает к мысли, что узники не люди, а рассходный материал. Ярче всего это происходит у команды мобилизованных подростков.",
 "f-wd698327": "Герой Джеки Чана — плейбой, полусыщик, полунаемник и целиком бабник. К нему обращается газетный магнат Имамура, у которого пропала дочь. Джеки пробирается на роскошный круизный лайнер, на котором разношерстная банда преступников держит свою жертву. Доступным лишь одному ему способом, Джеки удается изрядно подпортить путешествие этим подонкам и освободить прекраснейшую из женщин.",
 "f-wd1474616": "За провинность зазнавшегося юного мастера исключают из школы кунг-фу. Он попадает в сети злодеев, которые вовсю используют его умение махать руками и ногами в преступных целях.  По следам молодого бесшабашного мастера идет и полиция и его лучший друг. Успеет ли приятель вырвать его из кольца криминального окружения и направить талант лучшего ученика в мирное русло?!",
 "f-wd389348": "Ё Чжин — девушка-подросток, которая живет с овдовевшим отцом. Её лучшая подруга Чжэ Ёнг занимается проституцией, а Ё Чжин находит для неё клиентов и откладывает заработанные деньги на совместную поездку в Европу… Вскоре главная героиня сама становится проституткой, а ее отношения с клиентами и своим отцом складываются весьма непросто…",
 "f-wd1309886": "Фильм охватывает период наивысшей популярности группы, между альбомом 1976 года «Arrival» и альбомом 1977 года «The Album», песни из которых представлены в виде видеозарисовок.",
 "f-wd113149": "Когда Марго впервые встречает Дэниэла, напряжение между ними возникает мгновенно. Вскоре после их случайного знакомства выясняется, что Дэниэл — новый сосед Марго и ее мужа Лу.  28-летняя писательница Марго шесть лет замужем за Лу, успешным автором кулинарных книг. Оба счастливы в своей уютной размерен- ной жизни в пригороде Торонто и абсолютно уверены в своих чувствах. Эмоции, которые Марго начинает испытывать к новому приятелю совершенно не похожи на то, что происходит у них с мужем. Лу — забавный, добрый, милый, и постоянно готовит курицу, работая над очередным кулинарным бестселлером (и это немного раздражает Марго). А с симпатичным соседом — жаркое лето, прогулки, разговоры, многозначительные взгляды, ночной бассейн, щемящее чувство запрета. Марго окончательно теряет равновесие…",
 "f-wd1321282": "В 1890 году, Понтус, голодающий писатель, блуждает по улицам Христиании, в поисках любви и шанса издать его рукописи. Но все, что он встречает — это поражение и страдание, и смысл жизни постепенно уходит. Но все же он сохраняет человеческое достоинство и гордость.",
 "f-wd661422": "Последняя декада складывалась неудачно на Небе. Управляющая райскими делами — обольстительная Ардан, обеспокоена тем, что в последние годы количество душ, достойных попасть в рай, практически равно нулю. Что не скажешь об аде, на контрольно-пропускном пункте которого постоянно галдит разноперая живая очередь. Все говорит о том, что ад, судя по всему, победил в борьбе между добром и злом…Два ангела — посланники Ада и Рая — принимают женский облик и спускаются на землю. Ангел добра, добродетельная блондинка Лола послан для того, чтобы спасти жизнь и душу отчаявшегося боксера Мани, о котором молится его мать. Бедолага только что проиграл бой, из-за травм он вынужден бросить спорт, мало того, крупный долг висит над ним дамокловым мечом.",
 "f-wd766637": "Франческо — уверенный в себе, независимый молодой архитектор, который работает вместе со своей женой Мартой и их старым другом Паоло. Но это не мешает Марте и Паоло уже много лет быть любовниками. Однако у этого любовного треугольника есть и другие пикантные оттенки, которые интригующе закручивают сюжет.",
 "f-wd1306553": "А-Фэй — имя главного героя, который кажется благополучным человеком: его любят женщины, он не нуждается в деньгах. Но тайна происхождения, непроясненность прошлого, мешает ему укорениться в настоящем: для человека старой китайской культуры разрыв в цепи поколений — не частная неурядица, а корневая беда.\r Герой строит новую систему координат: уклоняйся от обязательств, остерегайся привязанностей, избегай закрепощающих чувств…",
 "f-wd483909": "Молодая пара встречается уже два года. Девушка боится, что юноша может от нее устать. Постоянные истерики приводят к тому, что однажды Чи-Ву находит в себе силы заняться сексом с Си-Хи лишь только после того, как она предлагает ему представить себе другую женщину.  Как можно оставить о себе свежее и новое впечатление от каждой встречи у своего возлюбленного? Можно прибегнуть к пластической хирургии, полностью изменяя собственную внешность…",
 "f-wd2627763": "Красавец-блондин Азур с глазами цвета ясного неба — сын владелицы замка. Брюнет Азмар, чьи очи черны, как самая темная ночь Востока, — сын кормилицы. В зеленой и процветающей стране они росли, как родные братья. Судьба разлучила друзей, но они не забыли счастья своего детства и сказок о далекой стране мечты, о которой когда-то рассказывала им кормилица.  Став взрослым, сильный и умный Азур отправляется на поиски этой загадочной страны, где обитает могущественная Фея Джиннов. Сказка детства привела в эти края и храброго Азмара, который тоже полон решимости во что бы то ни стало разыскать Фею, невзирая на все опасности и чары этого волшебного государства, где встречаются день и ночь, где счастье и любовь — на волоске от смерти…",
 "f-wd19776287": "Своенравное поведение командира Лэн Фэна, офицера спецназа, часто вызывает недовольство у вышестоящего начальства. Во время штурма тайного убежища наркоторговцев Фэн нарушает прямой приказ и спасает положение, метким выстрелом убивая наркобарона. После отбывания срока за неподчинение приказам и неповиновение, Фэна, благодаря его навыкам и храбрости, принимают в китайский элитный отряд под названием «Wolf Warrior». Пройдя вместе со своими подчинёнными ряд суровых занятий и тренировок, он, в итоге, собирает команду, которую может назвать своей собственной. Но дело принимает плохой оборот, когда во время финальной стадии учений они попадают в засаду, устроенную высококвалифицированными иностранными наёмниками во главе с Томом, поклявшимся отомстить Лэн Фэну и его людям за убийство своего бывшего работодателя. Линия фронта очерчена, и отступать или сдаваться не собирается ни одна из сторон.",
 "f-wd24278862": "В декабре 1941 года Япония расширяет оккупацию соседних стран в Юго-Восточной Азии. Железная дорога от Тяньцзинь Нанкин в Восточном Китае стала ключевым маршрутом для военных перевозок под усиленной охраной японских солдат. Работник железной дороги Ма Юань организовывает команду борцов за свободу. Используя свои глубокие знания железнодорожных сетей, он со своими людьми устраивает засады для японских солдат и ворует их припасы, чтобы накормить голодающих соотечественников.  Местные называют своих героев «железнодорожными тиграми». И когда борцы за свободу оказываются на неправильной стороне путей при отправке подкрепления японцам в провинцию Шаньдун, Ма Юань решается на опасный поступок — взорвать тщательно охраняемый железнодорожный мост.",
 "f-wd2750748": "Бывший легендарный убийца Кэнсин Химура стал скитальцем самураем, предлагающим помощь и защиту нуждающимся, чтобы искупить свои прошлые поступки. Во время своих скитаний Кэнсин столкнется с Каору Камией. Ее отец открыл школу кэндо в Токио и Каору работает там инструктором. Отношения Кэнсина и Каору начинают развиваться, но Кэнсина по-прежнему преследует его ужасное прошлое",
 "f-wd496752": "Син Э переезжает вместе со своим сыном Чжуном в Мильян, родной городок ее недавно скончавшегося мужа. Пока она пытается совладать с собой и начать новую жизнь, происходит еще одно трагическое событие.",
 "f-wd1361789": "В 221 году до н. э. Ин Чжэн, повелитель царства Цинь, пытается подчинить себе все китайские княжества. Он вошел в историю как первый император Китая.",
 "f-wd19801741": "В 1933 году борцы за независимость Кореи планируют убийство важных лиц японской администрации — губернатора Кёнсона Мамору Кавагути и прояпонского магната Кан Ин-гука. Агент сопротивления Ём Сок-чин поручает миссию девушке-снайперу Ан Ог-юн, специалисту-подрывнику Хван Док-саму и Чу Сан-оку. Группа прибывает в Кёнсон, не зная, что один из них работает на японцев и нанял киллеров для устранения членов группы.",
 "f-wd28775783": "Блондинка, хипстер, бизнесмен, бомж — разношерстная группа изолирована в кафе, когда всех выходящих из него начинает обстреливать снайпер. Выйти наружу смертельно опасно, но и внутри страсти разгораются нешуточные. Обстановка накаляется до предела, когда предположение, что главный источник угрозы находится внутри, находит подтверждение. Больше беспредела, ведь заказ кофе может стоить вам жизни",
 "f-wd4009792": "Главная героиня, итальянка Джемма, отправляется вместе со своим 16-летним сыном Пьетро в Сараево. Она хочет показать Пьетро его родной город и рассказать о его отце Диего, которого он никогда не знал. В аэропорту Джему встречает ее давний друг и Гойко, который в 1984 году во время зимней Олимпиады познакомил ее с фотографом из Генуи Диего — любовью всей ее жизни.",
 "f-wd1001759": "В начале XX века во время японской оккупации Китая самураи, кичившиеся своим непобедимым каратэ, жестоко убили миролюбивого учителя кунг-фу Хо. Деморализованный народ даже не помышлял о сопротивлении. Устрашились все, кроме Жень Чена, самого одаренного ученика погибшего мастера. Узнав о случившемся, герой клянется во что бы то ни стало отомстить убийцам. И когда приходит час возмездия, стонущий под пятой захватчиков Шанхай превращается в поле грандиозной битвы между дерзким одиночкой и сонмом опаснейших врагов.",
 "f-wd496378": "Когда офицер Гён Чжин Ё слышит женщину, кричащую, что кто-то схватил её кошелек, она не может позволить такому преступлению пройти незамеченным. Гён Чжин бросается в погоню за Мён Гу Го, ловит его, и доставляет в отделение полиции. Там, она обнаруживает, что Мён Гу — не преступник, а наоборот, храбрый гражданин, который пытался поймать настоящего грабителя.",
 "f-wd498765": "Молодой университетский лектор с беременной подружкой живет в густонаселенном жилом комплексе. Когда постоянно лающая где-то по соседству собака переполняет чашу его терпения, скромный очкарик решает действовать.",
 "f-wd30644590": "Вместе с родителями и обожаемым старшим братом Ю-соком 21-летний Чин-сок переезжает в новый дом. Прежний хозяин оставил свои вещи в одной комнате, и отец говорит сыновьям в неё не заходить, но Чин-сок постоянно слышит оттуда странные звуки. Парень готовится к экзаменам и принимает таблетки, поэтому семья считает, что это ему слышится. Однажды на глазах младшего брата Ю-сока похищают. Он возвращается через 19 дней, ничего не помнит о своём исчезновении и кажется брату слегка другим человеком.",
 "f-wd1659521": "Жизнь 18-летнего Симона с синдромом Аспергера переворачивается с ног на голову, когда его брата Сама бросает девушка. Для нормального существования Симону нужна упорядоченность - чтобы все было на своих местах: распорядок дня, еда, одежда, неделя за неделей. Именно Сам постоянно заботится о брате. А когда Сам впадает в депрессию из-за разрыва со своей девушкой, мир Симона обращается в хаос. Симон пытается вернуть всё на круги своя и ставит себе задачу: найти Саму новую девушку.",
 "f-wd1507424": "Когда-то полковник сражался за свободу и братство. Но те дни прошли, и он тщетно ждёт пенсии в небольшом латиноамериканском городке вместе с больной женой. Ждёт уже 27 лет… Каждое утро он просыпается с мыслью о пенсии, ждёт, что с минуты на минуту ему её переведут. А мимо проносится жизнь с её маленькими радостями и горестями. Над полковником смеются, его жалеют, и единственная его надежда на лучшую жизнь — бойцовый петух, когда-то принадлежащий его погибшему сыну.",
 "f-wd258800": "Педро — привлекательный дантист-гомосексуалист и к тому же медведь, живущий активной половой жизнью. Он предлагает своей старшей сестре Виолете позаботиться о ее 9-летнем сыне Бернандо, пока та будет отдыхать в течение двух недель в Индии со своим новым бойфрендом-хиппи. Педро меняет свое сексуальное поведение, но вскоре выясняет, что Бернандо умен не по годам и вполне взросло относится к жизни.  Когда Виолету арестовывают в Индии, Педро автоматически становится опекуном мальчика, который обязан воспитывать ребенка. Когда отношения между дядей и племянником постепенно становятся более крепкими благодаря любви, дружбе и привязанности, мать Виолеты, Тереза, начинает предъявлять права на внука, потому как считает, что ребенок не должен оставаться в руках гомосесуалиста…",
 "f-wd3826202": "Действие фильма происходит во время перехода Чили к демократии. Заключенный выходит из тюрьмы по амнистии для арестантов, не запятнавших руки кровью, которую одобрил новый президент. Выйдя на свободу, он совсем не спешит благодарить освободителей, напротив его намерения полны жажды мести тем людям, которые злоупотребляли своей властью в тюрьме.",
 "f-wd2715312": "Мистический триллер «Монах» — экранизация классического готического романа Мэтью Льюиса, повествующего о взлетах и падениях уважаемого испанского монаха-капуцина Амбросио, который впервые увидел свет еще в 1796 году. Действие фильма разворачивается в XVIII веке. Притворившись юной послушницей, ведьма Матильда совращает Амбросио, и это становится известно суду Инквизиции. Желание избегнуть страшных мучений и казни толкает капуцина на сговор с Дьяволом, но и здесь его поджидает обман…",
 "f-wd2260885": "В кинотеатре происходит просмотр фильма ужасов о постепенно теряющем зрение внушительных размеров «мальчике» маньяке-офтальмологе Джонни  который под гипнотическим воздействием своей странной матери  убивает людей и вырезает им глазные яблоки. Фильм про плохого «плохого мальчика» Джона и его сумасшедшую мамочку вместе со всеми в кинотеатре смотрят также и две подружки — Пэтти и Линда. И в то время, как одна из девушек в полном восторге от кино и с удовольствием «внимает» экранному насилию, её подруга находится в противоположном состоянии — ей плохо, у нее начинаются параноидальные страхи и слуховые галлюцинации, вызванные гипнотической составляющей фильма. Которая впрочем подействовала не только на неё, но и на самого настоящего маньяка убийцу.",
 "f-wd300622": "Ван Бо и Ван Ли – «сладкая парочка» авантюристов, промышляющих воровством и рэкетом – и в мыслях не держали, что простофиля, готовый без тени сомнения отдать им все свои наличные, заставит их не просто отказаться от кражи, но даже изменить жизненную философию.",
 "f-wd50143448": "Студент первого курса полицейской академии Цинь Фэн прибывает в Америку на свадьбу кузена Тан Жэня. Но сразу же выясняется, что невеста уже давно вышла замуж за другого, а неугомонный родственник вытащил своего сообразительного брата в Штаты для участия в конкурсе детективов с призовым фондом 5 миллионов долларов. Лучшие умы со всего света собрались, чтобы выяснить, кто убил внука влиятельного бизнесмена из местного Чайнатауна, и на это у них есть всего семь дней.",
 "f-wd2529456": "1956 год. Япония накануне принятия закона, запрещающего проституцию. В своей последней картине Мидзогути рассказывает о том, как живут несколько женщин из «веселого дома». Если закон будет принят, героини ленты окажутся в тюрьме. А пока они живут в ожидании постоянного заработка и завидуют Ёри, у которой такая работа есть.",
 "f-wd5509114": "Эдди — трансвестит и звезда в одном из гей-клубов Токио. Он проводит время работая в клубе, снимаясь в порнофильмах знакомого режиссёра, принимая наркотики и стараясь найти любовь. Он хочет добиться любви одного из менеджеров клуба, конкурируя в этом с другим трансвеститом.",
 "f-wd55223237": "Все складывается очень плохо для режиссера и съемочной группы, снимающих низкобюджетный фильм о зомби на заброшенном японском объекте времен Второй мировой войны, когда на них нападают настоящие зомби.",
 "f-wd1021977": "Китти по жизни не очень везло с мужчинами, пока ей не встретился приятный полицейский. И только жизнь начала налаживаться, как отца девушки убивают. Вне себя от злости Китти вламывается в офис убийцы и устраивает пальбу, но там оказывается другая женщина-киллер, которая спасает дурочку. Новой знакомой нравится Китти, и она решает сделать из неё профессиональную убийцу.",
 "f-wd2992506": "Каждый год восемь мастеров кун-фу из монастырей Шаолиня собирались вместе. Однажды после долгих обсуждений, рассмотрев все известные виды кун-фу, они соединили воедино самое лучшее в этих боевых искусствах. Так появилась новая техника, названная «Восемь ступеней Змеи и Журавля»…"
};
